  globalThis.priceTable = (p, q) => { const row = (l, n, b) => (n || b ? `<div class="drow"><span>${esc(l)}</span><span>${b ? '<b>' : ''}${kzt(n)}${b ? '</b>' : ''}</span></div>` : ''); return `<p class="note">${esc(routeText(p.route))} · ${p.km} ${esc(LF.unit('km'))} · ${esc(MODE_L[p.route.mode])} · ${esc(T('срок', 'Laufzeit', 'lead time', 'мерзім'))} ${p.route.lead} ${esc(T('раб. дн.', 'AT', 'business days', 'жұмыс күні'))} · ${esc(T('тарифных паллет', 'frachtpflichtige Pal.', 'chargeable pallets', 'тарифтік паллет'))} ${p.ch}</p><div class="dlist">${row(T('Фрахт (тариф линии' + (p.terms ? ', скидка ' + p.terms.disc + ' %' : '') + ')', 'Fracht (Linientarif' + (p.terms ? ', Rabatt ' + p.terms.disc + ' %' : '') + ')', 'Freight (line tariff' + (p.terms ? ', discount ' + p.terms.disc + ' %' : '') + ')', 'Фрахт (желі тарифі' + (p.terms ? ', жеңілдік ' + p.terms.disc + ' %' : '') + ')'), p.freight, true)}${row(T('Топливная надбавка', 'Treibstoffzuschlag', 'Fuel surcharge', 'Отын үстемесі'), p.fuel)}${row(T('Надбавка ADR', 'ADR-Zuschlag', 'ADR surcharge', 'ADR үстемесі'), p.adr)}${row(T('Перегрузка в хабе', 'Umschlag im Hub', 'Hub handling', 'Хабта қайта тиеу'), p.handling)}${row(T('Экспресс', 'Express', 'Express', 'Экспресс'), p.express)}${row(T('Итого без НДС', 'Netto', 'Net', 'ҚҚС-сыз'), p.net)}${row(T('НДС 16 %', 'MwSt. 16 %', 'VAT 16 %', 'ҚҚС 16 %'), p.vat)}${row(T('Страховая премия (без НДС)', 'Versicherungsprämie (ohne MwSt.)', 'Insurance premium (no VAT)', 'Сақтандыру сыйлықақысы (ҚҚС-сыз)'), p.premium)}${row(T('Итого к оплате', 'Gesamt', 'Total', 'Барлығы'), p.gross, true)}</div><p class="note">${esc(fxLine(p.gross))}</p>`; };
