    const seg = `<div class="pill-tabs" style="margin-bottom:10px" data-task-seg>${[[false, T('Мои', 'Meine', 'Mine', 'Менікі')], [true, T('Все', 'Alle', 'All', 'Барлығы')]].map(([v, l]) => `<span class="pill-tab${!!all === v ? ' active' : ''}" data-act="cmTkSeg" data-v="${v ? 1 : 0}">${esc(l)}</span>`).join('')}</div>`;
    const people = [['', T('Мне', 'Mir', 'Me', 'Маған')]].concat([...new Set(['Sarah Johnson'].concat((S.users || []).map(u => u.name)))].filter(n => n !== me).map(n => [n, n]));
    const empty = `<p class="note" data-task-empty>${esc(all ? T('Задач нет.', 'Keine Aufgaben.', 'No tasks.', 'Тапсырма жоқ.') : T('Для вас задач нет.', 'Keine Aufgaben für Sie.', 'No tasks for you.', 'Сізге тапсырма жоқ.'))}</p>`;
    return `<div class="grid2">${card(T('Задачи', 'Aufgaben', 'Tasks', 'Тапсырмалар') + ' · ' + list.filter(t => !t.done).length, seg + (rows || empty))}${w ? card(T('Новая задача', 'Neue Aufgabe', 'New task', 'Жаңа тапсырма'), `<label class="fl">${esc(T('Что сделать', 'Was ist zu tun', 'What to do', 'Не істеу керек'))}${inp('tk_title', T('Новая задача', 'Neue Aufgabe', 'New task', 'Жаңа тапсырма'), 'text', ' maxlength="200"')}</label><label class="fl">${esc(T('Срок', 'Fällig am', 'Due date', 'Мерзімі'))}${inp('tk_due', '', 'date')}</label><label class="fl">${esc(T('Исполнитель', 'Zuständig', 'Assignee', 'Орындаушы'))}${selc('tk_who', people)}</label><label class="fl">${esc(T('Клиент', 'Kunde', 'Customer', 'Клиент'))}${selc('tk_cust', [['', '—'], ...S.customers.map(c => [c.id, c.name])])}</label><button class="btn primary" data-act="cmTaskAdd">${esc(T('Создать', 'Anlegen', 'Create', 'Құру'))}</button>${msg()}`) : ''}</div>`;
